package dev.playerjoinnotifier.platform;

import dev.playerjoinnotifier.core.ChimeSynth;

import javax.sound.sampled.AudioFormat;
import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.Clip;
import javax.sound.sampled.LineEvent;

/**
 * Plays the short chime with the JDK's built-in Java Sound (no libraries, no sound files; the tone is
 * generated by {@link ChimeSynth}). Works the same on Linux, Windows and macOS. Fails with an exception
 * (e.g. no audio device), which the caller logs without affecting the game.
 */
public final class SoundPlayer {
	private static final AudioFormat FORMAT = new AudioFormat(ChimeSynth.SAMPLE_RATE, 16, 1, true, false);

	private SoundPlayer() {
	}

	/** Starts playing and returns right away (the clip closes itself when done). */
	public static void play(boolean join, int volumePercent) throws Exception {
		if (volumePercent <= 0) {
			return;
		}
		byte[] pcm = ChimeSynth.render(join, volumePercent);
		Clip clip = AudioSystem.getClip();
		clip.addLineListener(event -> {
			if (event.getType() == LineEvent.Type.STOP) {
				clip.close();
			}
		});
		clip.open(FORMAT, pcm, 0, pcm.length);
		clip.start();
	}
}
